// @generated by:gauntlet run:anatoly-orion-recon
mod common;

use anatoly::{
    scan::{Report, scan_configured},
    scan_options::ScanOptions,
};
use common::{Server, limits, response};
use serde_json::Value;
use std::{
    fs,
    path::PathBuf,
    process::{Command, Output},
    sync::atomic::{AtomicU64, AtomicUsize, Ordering},
};

static NEXT_FILE: AtomicU64 = AtomicU64::new(0);

#[derive(Default)]
struct Reports(Vec<PathBuf>);

impl Reports {
    fn save(&mut self, value: &Value) -> PathBuf {
        let unique = NEXT_FILE.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!(
            "anatoly-technology-offline-{}-{unique}.json",
            std::process::id()
        ));
        let file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&path)
            .unwrap();
        self.0.push(path.clone());
        serde_json::to_writer(file, value).unwrap();
        path
    }
}

impl Drop for Reports {
    fn drop(&mut self) {
        for path in &self.0 {
            fs::remove_file(path).unwrap();
        }
    }
}

fn options() -> ScanOptions {
    let mut settings = ScanOptions {
        samples: 1,
        discover: false,
        no_hypotheses: true,
        ..ScanOptions::default()
    };
    settings.network.no_proxy = true;
    settings
}

fn observed_report(server: &Server) -> Value {
    let target = scan_configured(&server.url, limits(), &options()).unwrap();
    serde_json::to_value(Report::new(vec![target])).unwrap()
}

fn cli(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_anatoly"))
        .args(args)
        .output()
        .unwrap()
}

#[test]
fn t_ac_13_offline_comparison_detects_technology_changes_when_hypotheses_are_disabled() {
    let observations = AtomicUsize::new(0);
    let server = Server::new(move |_| {
        let version = if observations.fetch_add(1, Ordering::Relaxed) == 0 {
            "4.9.0"
        } else {
            "5.8.1"
        };
        response(
            "200 OK",
            &format!("X-Powered-By: Craft CMS {version}\r\n"),
            "application",
        )
    });
    let before = observed_report(&server);
    let after = observed_report(&server);
    assert!(
        before["targets"][0]["signals"]
            .as_array()
            .unwrap()
            .is_empty()
    );
    assert!(
        after["targets"][0]["signals"]
            .as_array()
            .unwrap()
            .is_empty()
    );
    let mut reports = Reports::default();
    let baseline = reports.save(&before);
    let current = reports.save(&after);

    let output = cli(&[
        "compare",
        baseline.to_str().unwrap(),
        current.to_str().unwrap(),
        "--json",
    ]);

    assert_eq!(output.status.code(), Some(1));
    let comparison: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(comparison["changed"], true);
    assert_eq!(comparison["changes"].as_array().unwrap().len(), 1);
    let change = &comparison["changes"][0];
    assert_eq!(change["change"], "changed");
    assert_eq!(
        change["baseline"]["technologies"],
        before["targets"][0]["technologies"]
    );
    assert_eq!(
        change["current"]["technologies"],
        after["targets"][0]["technologies"]
    );
    assert_eq!(server.paths.lock().unwrap().len(), 2);
}

#[test]
fn t_ac_13_offline_explanation_preserves_technology_runtime_and_coverage_scope() {
    let server = Server::new(|_| response("200 OK", "X-Powered-By: Craft CMS\r\n", "application"));
    let report = observed_report(&server);
    let mut reports = Reports::default();
    let input = reports.save(&report);

    let output = cli(&["explain", input.to_str().unwrap(), "--json"]);

    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let explanation: Value = serde_json::from_slice(&output.stdout).unwrap();
    let target = &explanation["targets"][0];
    assert_eq!(target["technologies"], report["targets"][0]["technologies"]);
    assert_eq!(target["runtime"], report["targets"][0]["runtime"]);
    assert_eq!(
        target["coverage_scope"],
        report["targets"][0]["analysis"]["coverage_scope"]
    );
    assert!(target["version"].is_null());
    assert_eq!(server.paths.lock().unwrap().len(), 1);
}

#[test]
fn t_ac_13_watch_emits_a_technology_change_with_no_exact_php_or_hypothesis_changes() {
    let observations = AtomicUsize::new(0);
    let server = Server::new(move |_| {
        let product = if observations.fetch_add(1, Ordering::Relaxed) == 0 {
            "Craft CMS"
        } else {
            "WordPress"
        };
        response(
            "200 OK",
            &format!("X-Powered-By: {product}\r\n"),
            "application",
        )
    });

    let output = cli(&[
        "watch",
        &server.url,
        "--profile",
        "quick",
        "--samples",
        "1",
        "--iterations",
        "2",
        "--interval",
        "1",
        "--delay-ms",
        "0",
        "--no-proxy",
        "--no-hypotheses",
        "--json",
    ]);

    assert_eq!(output.status.code(), Some(2));
    let watch: Value = serde_json::from_slice(&output.stdout).unwrap();
    let events = watch["events"].as_array().unwrap();
    assert_eq!(events.len(), 2);
    assert_eq!(events[0]["type"], "baseline");
    assert_eq!(events[1]["type"], "change");
    for (event, name) in events.iter().zip(["Craft CMS", "WordPress"]) {
        let state = &event["state"];
        assert!(state["version"].is_null());
        assert!(state["signals"].as_array().unwrap().is_empty());
        assert_eq!(state["runtime"]["status"], "unknown");
        assert_eq!(state["technologies"][0]["name"], name);
    }
    assert_eq!(server.paths.lock().unwrap().len(), 2);
}

#[test]
fn t_ac_14_html_prefix_limit_discards_late_attribution_and_reports_incomplete_analysis() {
    let body = format!(
        "{}<footer>Powered by CraftCMS</footer>",
        "<div></div>".repeat(1100)
    );
    let server = Server::new(move |_| response("200 OK", "", &body));
    let mut budget = limits();
    budget.max_body = 32_768;
    let mut settings = options();
    settings.no_hypotheses = false;

    let report =
        serde_json::to_value(scan_configured(&server.url, budget, &settings).unwrap()).unwrap();

    assert!(report["technologies"].as_array().unwrap().is_empty());
    assert!(report["version"].is_null());
    assert!(report["evidence"].as_array().unwrap().is_empty());
    assert_eq!(report["analysis"]["coverage_complete"], false);
    assert!(
        report["analysis"]["gaps"]
            .as_array()
            .unwrap()
            .iter()
            .any(|gap| {
                let text = gap.as_str().unwrap().to_ascii_lowercase();
                text.contains("html")
            }),
        "{report}"
    );
    assert_eq!(server.paths.lock().unwrap().len(), 1);
}

#[test]
fn t_ac_14_malformed_comment_and_quote_inputs_never_panic_or_forge_exact_php_evidence() {
    for body in [
        "<!-- <meta name=generator content='Craft CMS'> PHP/8.4.26",
        "<p title='unterminated Powered by CraftCMS PHP/8.4.26",
        "<script><meta name=generator content='Craft CMS'> PHP/8.4.26",
        "<template><p>Powered by CraftCMS PHP/8.4.26",
    ] {
        let server = Server::new(move |_| response("200 OK", "", body));

        let report = observed_report(&server);

        let target = &report["targets"][0];
        assert!(target["version"].is_null(), "{body}: {report}");
        assert!(target["evidence"].as_array().unwrap().is_empty());
        assert_eq!(target["verdict"], "inconclusive");
    }
}
